"""
SVWS Training module v3 — router tự chứa cho svws-deploy (FastAPI + SQLModel)
Gắn vào app chính:   from training import router as training_router
                     app.include_router(training_router)
ENV:  TRN_ADMIN_KEY      (bắt buộc — khóa quản trị: duyệt tài khoản, xem điểm, CSV)
      DATABASE_URL       (dùng chung Postgres; thiếu -> SQLite ./training.db)
      TRN_EMP_DOMAINS    (domain email công ty, VD "songviet.vn" hoặc "songviet.vn,svws.vn";
                          đặt rồi: chỉ email đúng domain mới đăng ký được tài khoản NHÂN VIÊN;
                          chưa đặt: nhận mọi email nhưng luôn chờ admin duyệt)
      SMTP_HOST/SMTP_PORT/SMTP_USER/SMTP_PASS/SMTP_FROM (tùy chọn — có đủ thì xác minh
                          email bằng mã OTP và kích hoạt ngay; thiếu thì chờ admin duyệt)
Giao diện: static/training/index.html
Đăng nhập: NHÂN VIÊN và SINH VIÊN đều dùng email + mật khẩu tự đặt.
"""
import os, re, csv, io, time, base64, secrets, hashlib, smtplib, datetime as dt
from email.mime.text import MIMEText
from typing import Optional
from fastapi import APIRouter, HTTPException, Query, Request
from fastapi.responses import FileResponse, HTMLResponse, Response, JSONResponse, StreamingResponse
from pydantic import BaseModel
from sqlmodel import SQLModel, Field, Session, create_engine, select, or_

DATABASE_URL = os.getenv("DATABASE_URL", "sqlite:///./training.db")
if DATABASE_URL.startswith("postgres://"):
    DATABASE_URL = DATABASE_URL.replace("postgres://", "postgresql://", 1)
ADMIN_KEY = os.getenv("TRN_ADMIN_KEY", "")
HTML_PATH = os.getenv("TRAINING_HTML", "static/training/index.html")
EMP_DOMAINS = [d.strip().lower() for d in os.getenv("TRN_EMP_DOMAINS", "").split(",") if d.strip()]
SMTP = {k: os.getenv("SMTP_" + k, "") for k in ("HOST", "PORT", "USER", "PASS", "FROM")}
OTP_MODE = bool(SMTP["HOST"] and SMTP["USER"] and SMTP["PASS"])

_engine = create_engine(DATABASE_URL, pool_pre_ping=True) if not DATABASE_URL.startswith("sqlite") \
          else create_engine(DATABASE_URL, connect_args={"check_same_thread": False})

class TrnStaff(SQLModel, table=True):
    __tablename__ = "trn_staff"
    id: Optional[int] = Field(default=None, primary_key=True)
    emp_code: str = Field(index=True, max_length=30)
    full_name: str = Field(max_length=80)
    email: str = Field(index=True, max_length=120)
    pw_hash: str = Field(max_length=128)
    salt: str = Field(max_length=32)
    status: str = Field(default="pending", max_length=12)     # pending / active / blocked
    otp_code: str = Field(default="", max_length=8)
    otp_expire: float = 0.0
    token: str = Field(default="", index=True, max_length=64)
    created: dt.datetime = Field(default_factory=dt.datetime.utcnow)
    last_login: Optional[dt.datetime] = None

class TrnStudent(SQLModel, table=True):
    __tablename__ = "trn_students"
    id: Optional[int] = Field(default=None, primary_key=True)
    student_code: str = Field(index=True, max_length=20, default="")
    full_name: str = Field(max_length=80)
    phone: str = Field(index=True, max_length=15)
    email: str = Field(index=True, max_length=120)
    school: str = Field(max_length=150)
    course: str = Field(max_length=100)
    pw_hash: str = Field(max_length=128)
    salt: str = Field(max_length=32)
    status: str = Field(default="pending", max_length=12)
    edu_email: bool = False
    otp_code: str = Field(default="", max_length=8)
    otp_expire: float = 0.0
    token: str = Field(default="", index=True, max_length=64)
    created: dt.datetime = Field(default_factory=dt.datetime.utcnow)
    last_login: Optional[dt.datetime] = None

class TrnResult(SQLModel, table=True):
    __tablename__ = "trn_results"
    id: Optional[int] = Field(default=None, primary_key=True)
    emp_code: str = Field(index=True, max_length=30)
    name: str = Field(max_length=80)
    dm: str = Field(default="", max_length=120)
    code: str = Field(default="", max_length=20)
    tech: str = Field(default="", max_length=200)
    score: str = Field(default="", max_length=20)
    pct: int = 0
    kq: str = Field(default="", max_length=20)
    d: str = Field(default="", max_length=40)
    ts: dt.datetime = Field(default_factory=dt.datetime.utcnow)

SQLModel.metadata.create_all(_engine)
router = APIRouter(prefix="/training", tags=["training"])

# ---------------- CHỐNG TÀI KHOẢN ẢO ----------------
DISPOSABLE = {"mailinator.com","10minutemail.com","guerrillamail.com","guerrillamail.info","sharklasers.com",
 "temp-mail.org","tempmail.com","tempmail.dev","yopmail.com","trashmail.com","getnada.com","dispostable.com",
 "maildrop.cc","mintemail.com","throwawaymail.com","fakeinbox.com","mytemp.email","tmpmail.org","mohmal.com",
 "emailondeck.com","spamgourmet.com","mail-temp.com","tempinbox.com","33mail.com","burnermail.io"}
EMAIL_RE = re.compile(r"^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$")

def norm_phone(p: str) -> str:
    p = re.sub(r"[\s.\-()]", "", p or "")
    if p.startswith("+84"): p = "0" + p[3:]
    elif p.startswith("84") and len(p) == 11: p = "0" + p[2:]
    return p

def valid_phone(p: str) -> bool:
    if not re.fullmatch(r"0(3|5|7|8|9)\d{8}", p): return False
    if len(set(p[1:])) <= 2: return False
    if p[1:] in ("123456789", "987654321"): return False
    return True

def check_email(e: str):
    e = (e or "").strip().lower()
    if not EMAIL_RE.fullmatch(e): raise HTTPException(422, "Email không đúng định dạng.")
    dom = e.split("@")[1]
    if dom in DISPOSABLE: raise HTTPException(422, "Không chấp nhận email dùng một lần.")
    return e, dom

_RL = {}
def rate_limit(ip: str, limit: int = 10, window: int = 3600):
    now = time.time()
    arr = [t for t in _RL.get(ip, []) if now - t < window]
    if len(arr) >= limit: raise HTTPException(429, "Quá nhiều lượt đăng ký từ địa chỉ này — thử lại sau 1 giờ.")
    arr.append(now); _RL[ip] = arr

def check_bot(website: str, ts: float, request: Request):
    if (website or "").strip(): raise HTTPException(422, "Đăng ký không hợp lệ.")
    if ts and time.time()*1000 - ts < 3000: raise HTTPException(422, "Bạn thao tác quá nhanh — vui lòng thử lại.")
    rate_limit(request.client.host if request.client else "?")

def hash_pw(pw: str, salt: str) -> str:
    return hashlib.pbkdf2_hmac("sha256", pw.encode(), salt.encode(), 100000).hex()


# ---- Tài khoản quản trị gieo sẵn từ biến môi trường (Render) ----
def _seed_admin():
    email = os.environ.get("TRN_ADMIN_EMAIL", "").strip().lower()
    pw = os.environ.get("TRN_ADMIN_PW", "")
    if not email or not pw:
        return
    try:
        with Session(_engine) as s:
            st = s.exec(select(TrnStaff).where(TrnStaff.email == email)).first()
            salt = secrets.token_hex(8)
            if st is None:
                st = TrnStaff(emp_code="ADMIN", full_name="Quản trị SVWS", email=email,
                              salt=salt, pw_hash=hash_pw(pw, salt), status="active")
            else:
                st.salt = salt
                st.pw_hash = hash_pw(pw, salt)
                st.status = "active"
                st.otp_code = ""
            s.add(st)
            s.commit()
    except Exception:
        pass

_seed_admin()

def send_otp(email: str, code: str) -> bool:
    try:
        msg = MIMEText("Ma xac minh SVWS Training cua ban: %s (hieu luc 15 phut)." % code, "plain", "utf-8")
        msg["Subject"] = "SVWS Training - Ma xac minh"
        msg["From"] = SMTP["FROM"] or SMTP["USER"]; msg["To"] = email
        with smtplib.SMTP(SMTP["HOST"], int(SMTP["PORT"] or 587), timeout=15) as s:
            s.starttls(); s.login(SMTP["USER"], SMTP["PASS"]); s.sendmail(msg["From"], [email], msg.as_string())
        return True
    except Exception:
        return False

def arm_otp(obj) -> None:
    if OTP_MODE:
        obj.otp_code = "%06d" % secrets.randbelow(1000000); obj.otp_expire = time.time() + 900
        if not send_otp(obj.email, obj.otp_code):
            obj.otp_code = ""; obj.otp_expire = 0

def _check_admin(key: str):
    if not ADMIN_KEY or key != ADMIN_KEY:
        raise HTTPException(403, "Sai khóa quản trị.")

def _actor_by_token(s: Session, token: str):
    st = s.exec(select(TrnStaff).where(TrnStaff.token == token, TrnStaff.status == "active")).first()
    if st: return st.emp_code, st.full_name
    sv = s.exec(select(TrnStudent).where(TrnStudent.token == token, TrnStudent.status == "active")).first()
    if sv: return sv.student_code, sv.full_name
    raise HTTPException(401, "Token không hợp lệ — đăng nhập lại.")

def _login(obj, password, label):
    if not obj or obj.pw_hash != hash_pw(password, obj.salt):
        raise HTTPException(401, "Sai thông tin đăng nhập.")
    if obj.status == "pending": raise HTTPException(403, label + " đang chờ duyệt/xác minh — vui lòng quay lại sau.")
    if obj.status == "blocked": raise HTTPException(403, "Tài khoản đã bị khóa — liên hệ SVWS.")
    obj.token = secrets.token_hex(16); obj.last_login = dt.datetime.utcnow()

def _verify(s: Session, obj, otp: str):
    if not obj or not obj.otp_code: raise HTTPException(404, "Không tìm thấy yêu cầu xác minh.")
    if time.time() > obj.otp_expire: raise HTTPException(410, "Mã đã hết hạn — đăng ký lại để nhận mã mới.")
    if otp.strip() != obj.otp_code: raise HTTPException(422, "Mã xác minh không đúng.")
    obj.status = "active"; obj.otp_code = ""; obj.otp_expire = 0
    s.add(obj); s.commit()

# ---------------- MODELS VÀO ----------------
class StaffRegisterIn(BaseModel):
    emp_code: str; full_name: str; email: str; password: str
    website: str = ""; ts: float = 0

class StudentRegisterIn(BaseModel):
    full_name: str; phone: str; email: str; school: str; course: str; password: str
    website: str = ""; ts: float = 0

class VerifyIn(BaseModel):
    email: str; otp: str

class LoginEmailIn(BaseModel):
    id: str; password: str

class ResultIn(BaseModel):
    token: str
    d: str = ""; name: str = ""; dm: str = ""; code: str = ""
    tech: str = ""; score: str = ""; pct: int = 0; kq: str = ""

class ActionIn(BaseModel):
    key: str; id: int; action: str    # approve | block | delete

# ---------------- NHÂN VIÊN ----------------
@router.post("/api/staff/register")
def staff_register(body: StaffRegisterIn, request: Request):
    check_bot(body.website, body.ts, request)
    code = body.emp_code.strip().upper(); name = body.full_name.strip()
    if not code or len(code) < 3: raise HTTPException(422, "Nhập mã nhân viên (VD: SV025).")
    if len(name) < 5 or " " not in name: raise HTTPException(422, "Nhập họ và tên đầy đủ.")
    email, dom = check_email(body.email)
    if EMP_DOMAINS and dom not in EMP_DOMAINS:
        raise HTTPException(422, "Tài khoản nhân viên phải dùng email công ty (@" + EMP_DOMAINS[0] + ").")
    if len(body.password) < 6: raise HTTPException(422, "Mật khẩu tối thiểu 6 ký tự.")
    with Session(_engine) as s:
        if s.exec(select(TrnStaff).where(or_(TrnStaff.email == email, TrnStaff.emp_code == code))).first():
            raise HTTPException(409, "Email hoặc mã nhân viên đã đăng ký — dùng nút Đăng nhập, hoặc liên hệ quản trị nếu quên mật khẩu.")
        salt = secrets.token_hex(8)
        st = TrnStaff(emp_code=code, full_name=name, email=email, salt=salt, pw_hash=hash_pw(body.password, salt))
        if not EMP_DOMAINS:
            pass                      # chưa khai domain công ty -> mọi đăng ký chờ admin duyệt
        else:
            arm_otp(st)               # đúng domain: có SMTP thì OTP kích hoạt ngay
        s.add(st); s.commit(); s.refresh(st)
        if st.otp_code:
            return {"mode": "otp", "message": "Đã gửi mã xác minh tới " + email + ". Nhập mã trong 15 phút để kích hoạt."}
        return {"mode": "manual", "message": "Đăng ký thành công! Tài khoản chờ quản trị SVWS duyệt — sau đó đăng nhập bằng email và mật khẩu đã đặt."}

@router.post("/api/staff/verify")
def staff_verify(body: VerifyIn):
    email = (body.email or "").strip().lower()
    with Session(_engine) as s:
        _verify(s, s.exec(select(TrnStaff).where(TrnStaff.email == email)).first(), body.otp)
        return {"ok": True, "message": "Xác minh thành công — đăng nhập ngay bằng email và mật khẩu."}

@router.post("/api/staff/login")
def staff_login(body: LoginEmailIn):
    email = (body.id or "").strip().lower()
    with Session(_engine) as s:
        st = s.exec(select(TrnStaff).where(TrnStaff.email == email)).first()
        _login(st, body.password, "Tài khoản nhân viên")
        s.add(st); s.commit(); s.refresh(st)
        return {"token": st.token, "name": st.full_name, "emp_code": st.emp_code}

@router.post("/api/login")
def old_login():
    raise HTTPException(410, "Cách đăng nhập đã đổi — tải lại trang (Ctrl+F5) để dùng bản mới: email + mật khẩu.")

# ---------------- SINH VIÊN ----------------
@router.post("/api/student/register")
def student_register(body: StudentRegisterIn, request: Request):
    check_bot(body.website, body.ts, request)
    name = body.full_name.strip()
    if len(name) < 5 or " " not in name: raise HTTPException(422, "Nhập họ và tên đầy đủ.")
    phone = norm_phone(body.phone)
    if not valid_phone(phone): raise HTTPException(422, "Số điện thoại không hợp lệ (di động Việt Nam 10 số).")
    email, dom = check_email(body.email)
    edu = dom.endswith(".edu.vn") or ".edu." in dom or dom.endswith(".ac.vn")
    school = body.school.strip(); course = body.course.strip()
    if len(school) < 3: raise HTTPException(422, "Nhập tên trường.")
    if not course: raise HTTPException(422, "Nhập khóa học (VD: K2023 — Kỹ thuật Môi trường).")
    if len(body.password) < 6: raise HTTPException(422, "Mật khẩu tối thiểu 6 ký tự.")
    with Session(_engine) as s:
        if s.exec(select(TrnStudent).where(or_(TrnStudent.email == email, TrnStudent.phone == phone))).first():
            raise HTTPException(409, "Email hoặc số điện thoại đã đăng ký. Dùng nút Đăng nhập, hoặc liên hệ SVWS nếu quên mật khẩu.")
        salt = secrets.token_hex(8)
        st = TrnStudent(full_name=name, phone=phone, email=email, school=school, course=course,
                        salt=salt, pw_hash=hash_pw(body.password, salt), edu_email=edu,
                        student_code="SVU-%04d" % (len(s.exec(select(TrnStudent.id)).all()) + 1))
        arm_otp(st)
        s.add(st); s.commit(); s.refresh(st)
        if st.otp_code:
            return {"mode": "otp", "message": "Đã gửi mã xác minh tới " + email + ". Nhập mã trong 15 phút để kích hoạt."}
        return {"mode": "manual", "message": "Đăng ký thành công! Tài khoản sẽ được SVWS duyệt trong 24 giờ làm việc — sau đó bạn đăng nhập bằng email/SĐT và mật khẩu đã đặt."}

@router.post("/api/student/verify")
def student_verify(body: VerifyIn):
    email = (body.email or "").strip().lower()
    with Session(_engine) as s:
        _verify(s, s.exec(select(TrnStudent).where(TrnStudent.email == email)).first(), body.otp)
        return {"ok": True, "message": "Xác minh thành công — đăng nhập ngay bằng email/SĐT và mật khẩu."}

@router.post("/api/student/login")
def student_login(body: LoginEmailIn):
    ident = (body.id or "").strip().lower()
    phone = norm_phone(ident)
    with Session(_engine) as s:
        st = s.exec(select(TrnStudent).where(or_(TrnStudent.email == ident, TrnStudent.phone == phone))).first()
        _login(st, body.password, "Tài khoản")
        s.add(st); s.commit(); s.refresh(st)
        return {"token": st.token, "name": st.full_name, "student_code": st.student_code}

# ---------------- GHI ĐIỂM ----------------
@router.post("/api/results")
def post_result(body: ResultIn):
    with Session(_engine) as s:
        code, name = _actor_by_token(s, body.token)
        r = TrnResult(emp_code=code, name=name, dm=body.dm, code=body.code,
                      tech=body.tech, score=body.score, pct=int(body.pct), kq=body.kq, d=body.d)
        s.add(r); s.commit()
        return {"ok": True}

# ---------------- QUẢN TRỊ ----------------
@router.get("/api/summary")
def summary(key: str = Query("")):
    _check_admin(key)
    with Session(_engine) as s:
        rows = s.exec(select(TrnResult)).all()
        staff = s.exec(select(TrnStaff)).all()
        studs = s.exec(select(TrnStudent)).all()
    best = {}
    for r in rows:
        k = (r.emp_code, r.code)
        b = best.get(k)
        if b is None:
            b = best[k] = {"emp_code": r.emp_code, "name": r.name, "code": r.code, "tech": r.tech,
                           "best_pct": r.pct, "kq": r.kq, "last": "", "tries": 0}
        if r.pct > b["best_pct"]: b["best_pct"] = r.pct; b["kq"] = r.kq
        b["tries"] += 1
        b["last"] = max(b["last"], r.ts.strftime("%d/%m/%Y %H:%M"))
    return {"staff_active": sum(1 for x in staff if x.status == "active"),
            "staff_pending": sum(1 for x in staff if x.status == "pending"),
            "students_active": sum(1 for x in studs if x.status == "active"),
            "students_pending": sum(1 for x in studs if x.status == "pending"),
            "total_results": len(rows),
            "summary": sorted(best.values(), key=lambda x: (x["emp_code"], x["code"]))}

def _acc_rows(model, s):
    return s.exec(select(model).order_by(model.created.desc())).all()

@router.get("/api/staff")
def staff_list(key: str = Query("")):
    _check_admin(key)
    with Session(_engine) as s:
        rows = _acc_rows(TrnStaff, s)
    return {"staff": [{"id": x.id, "emp_code": x.emp_code, "full_name": x.full_name, "email": x.email,
                       "status": x.status, "created": x.created.strftime("%d/%m/%Y %H:%M")} for x in rows]}

@router.get("/api/students")
def students(key: str = Query("")):
    _check_admin(key)
    with Session(_engine) as s:
        rows = _acc_rows(TrnStudent, s)
    return {"students": [{"id": x.id, "student_code": x.student_code, "full_name": x.full_name,
                          "phone": x.phone, "email": x.email, "edu": x.edu_email, "school": x.school,
                          "course": x.course, "status": x.status,
                          "created": x.created.strftime("%d/%m/%Y %H:%M")} for x in rows]}

def _apply_action(s: Session, obj, action: str):
    if not obj: raise HTTPException(404, "Không tìm thấy.")
    if action == "approve": obj.status = "active"; obj.otp_code = ""; s.add(obj)
    elif action == "block": obj.status = "blocked"; obj.token = ""; s.add(obj)
    elif action == "delete": s.delete(obj)
    else: raise HTTPException(422, "Hành động không hợp lệ.")
    s.commit()

@router.post("/api/staff/action")
def staff_action(body: ActionIn):
    _check_admin(body.key)
    with Session(_engine) as s:
        _apply_action(s, s.get(TrnStaff, body.id), body.action)
        return {"ok": True}

@router.post("/api/students/action")
def student_action(body: ActionIn):
    _check_admin(body.key)
    with Session(_engine) as s:
        _apply_action(s, s.get(TrnStudent, body.id), body.action)
        return {"ok": True}

@router.get("/api/results.csv")
def results_csv(key: str = Query("")):
    _check_admin(key)
    with Session(_engine) as s:
        rows = s.exec(select(TrnResult).order_by(TrnResult.ts)).all()
    buf = io.StringIO(); w = csv.writer(buf)
    w.writerow(["Thời điểm (server UTC)", "Mã", "Họ tên", "Nhóm", "Mã bài", "Công nghệ", "Điểm", "%", "Kết quả", "Giờ máy học viên"])
    for r in rows:
        w.writerow([r.ts.strftime("%Y-%m-%d %H:%M:%S"), r.emp_code, r.name, r.dm, r.code, r.tech, r.score, r.pct, r.kq, r.d])
    data = "\ufeff" + buf.getvalue()
    return StreamingResponse(io.BytesIO(data.encode("utf-8")), media_type="text/csv",
        headers={"Content-Disposition": "attachment; filename=svws_training_results.csv"})

# ---------------- TRANG GIAO DIỆN ----------------
@router.get("", include_in_schema=False)
@router.get("/", include_in_schema=False)
def training_app():
    if os.path.exists(HTML_PATH):
        return FileResponse(HTML_PATH, media_type="text/html")
    return HTMLResponse("<h3>Chưa có file giao diện — đặt bản APP tại " + HTML_PATH + "</h3>", status_code=404)

